3	/**
4	 * A minimalist implementation of a Bear, a bear can only eat other animals and not plants,
5	 * only the act method is unique to the bear.
6	 *
7	 * @version 1.0
8	 */
9	public class Bear extends CarnivoreAnimal
10	{
11	    
12	    /*///////////////////////////////////////////////////////////////
13	                                 CONSTANTS
14	    //////////////////////////////////////////////////////////////*/
15	    
16	    private static final int BREEDING_AGE = 25;
17	    private static final int MAX_AGE = 80;
18	    private static final double BREEDING_PROBABILITY = 0.115;
19	    private static final double HIBERNATION_BREEDING_FACTOR = 0.5;
